#include "KS/SRC/ks/wave_perturb_shared.h"

void WAVE_CopyPartition(
    const WavePartition *input,
    WavePartition *output);
void WAVE_RestrictPartition(
    WavePartition *partition,
    float minimum,
    float maximum);

__asm__(
    ".equ WAVE_CopyPartition__FPC13WavePartitionP13WavePartition, "
    "0x00379A88");
__asm__(
    ".equ WAVE_RestrictPartition__FP13WavePartitionff, "
    "0x003794B8");

static void WAVE_PrependDeadweight(const WavePartition *wpin, WavePartition *wpout, float weight)
{
	float min = wpin->guide[0], max = wpin->guide[wpin->N - 1];
	float epsilon = 0.0001f * (max - min);

	++wpout->guide;
	++wpout->guidestep;
	++wpout->weight;
	WAVE_CopyPartition(wpin, wpout);
	WAVE_RestrictPartition(wpout, min + epsilon, max);
	--wpout->guide;
	--wpout->guidestep;
	--wpout->weight;
	wpout->guide[0] = min;
	wpout->guidestep[0] = (min + epsilon) - min;
	wpout->weight[0] = weight;
	++wpout->N;
}
